edit('work/rules_engine/gm_runtime/scene-rules.mjs','export const CONDITIONAL_RULES={',"export const CONDITIONAL_RULES={\n  geneticLock:{source:'PHB基因锁17–36；901核心7/101',rules:'一阶自然1D10＋既往成功次数≥10；主动移动7XP，成功不耗XP，失败力量伤2和不可豁免剧痛10。二阶须一阶已开启，2D10＋既往次数（可随意一阶另＋2）≥20；主动整轮14XP，失败力量伤3和剧痛10。二阶玩家选力量/敏捷＋5内在及另2附加成功，迅捷切换；临时传奇资格随属性撤除。持续基数min(力量,意志)，二阶成功使一阶时限翻倍；两阶独立超限每轮记剧痛2、每三轮力量伤2，结束叠加兑现，并各按开启轮数抵抗结束剧痛。首次成功超常表现留主持叙述。原文明确的普通程序已接入，不采用RE替代版。',missing:['实际解锁履历、合格机会/主动意图及二阶所选属性','统一意志增强资格/基础费用，已有明确资格可调用基因锁增益','主动解除动作、只退二阶和同轮双开费用','临时HP撤除时伤槽过多的处置；毁灭性属性伤由承受者分配']},")
